import ast
import pathlib

bad = ok = 0
first = None
for p in sorted(pathlib.Path(".").rglob("*.py")):
    try:
        ast.parse(p.read_text(encoding="utf-8"))
        ok += 1
    except (SyntaxError, ValueError, UnicodeDecodeError) as exc:
        bad += 1
        if first is None:
            first = f"{p.as_posix()}: {type(exc).__name__}: {str(exc)[:160]}"
print(f"FAILED/TOTAL {bad}/{bad + ok}")
if first:
    print("first failure:", first)
